import{_ as a,o as n,c as t,ag as i}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"05 · 负载均衡","description":"","frontmatter":{"概念":"负载均衡","技能":"system-design","阶段":"2-基础组件","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"04 存储选型","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/05-load-balancing.md","filePath":"system-design/concepts/05-load-balancing.md","lastUpdated":null}'),e={name:"system-design/concepts/05-load-balancing.md"};function l(p,s,h,d,r,o){return n(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="_05-·-负载均衡" tabindex="-1">05 · 负载均衡 <a class="header-anchor" href="#_05-·-负载均衡" aria-label="Permalink to &quot;05 · 负载均衡&quot;">​</a></h1><blockquote><p><strong>前置</strong>：04 存储选型 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>负载均衡（Load Balancer, LB）是水平扩展的<strong>入口</strong>：它把用户请求分摊到多台后端机器上，让「加机器 = 加容量」成为可能。没有 LB 的集群，扩容毫无意义——请求全打在一台机器上，其余机器闲着。它是系统设计里最「基础」的基础组件，几乎所有规模大于单机的系统都从它开始。</p><p>对前端工程师来说，LB 并不陌生：Webpack DevServer 的 <code>proxy</code> 就是一台迷你 L7 负载均衡（按路径转发到不同后端），CDN 边缘节点本身也是「按地理位置调度的负载均衡」。区别在于：前端接触的是<strong>单机进程内的转发</strong>，生产环境的 LB 要考虑算法、健康检查、会话保持、自身高可用四件事。</p><p>本章围绕这四件事展开：L4 vs L7 怎么选、算法怎么配、后端挂了怎么剔除、用户会话怎么保持，最后讲 LB 自身的高可用（VIP 漂移）。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-l4-与-l7-两档转发" tabindex="-1">1. L4 与 L7：两档转发 <a class="header-anchor" href="#_1-l4-与-l7-两档转发" aria-label="Permalink to &quot;1. L4 与 L7：两档转发&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>L4（传输层）</th><th>L7（应用层）</th></tr></thead><tbody><tr><td>转发依据</td><td>IP + 端口</td><td>URL、Header、Cookie、请求体</td></tr><tr><td>代表</td><td>LVS / F5 / 云 LB</td><td>Nginx / HAProxy / Envoy</td></tr><tr><td>性能</td><td>极高（不解析报文）</td><td>较高（每请求解析开销）</td></tr><tr><td>能力</td><td>只转发不感知业务</td><td>可按路径/域名路由、改写、限流</td></tr><tr><td>适用</td><td>数据库/内部服务入口</td><td>Web API、微服务网关</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L4 架构（转发单元是「连接」）：</span></span>
<span class="line"><span>  客户端 ──► VIP ──► 后端1:3306</span></span>
<span class="line"><span>                └────► 后端2:3306      （MySQL 主从入口，只转发端口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>L7 架构（转发单元是「请求」，可按路径分流）：</span></span>
<span class="line"><span>  客户端 ──► Nginx ──┬─► /api/* ──► 应用集群</span></span>
<span class="line"><span>                     ├─► /static/* ─► 静态资源服务器</span></span>
<span class="line"><span>                     └─► /ws/*  ───► WebSocket 集群</span></span></code></pre></div><p>实践原则：<strong>能用 L4 就用 L4</strong>（更简单更快），需要按内容路由、Header 改写、灰度分流时才上 L7。Web 系统基本 L7（Nginx），内部组件（数据库、消息队列）用 L4。</p><h4 id="_2-常见调度算法" tabindex="-1">2. 常见调度算法 <a class="header-anchor" href="#_2-常见调度算法" aria-label="Permalink to &quot;2. 常见调度算法&quot;">​</a></h4><table tabindex="0"><thead><tr><th>算法</th><th>机制</th><th>适用场景</th><th>注意</th></tr></thead><tbody><tr><td>轮询 Round Robin</td><td>依次分发</td><td>后端同构、无状态</td><td>机器性能不一则慢机器被拖累</td></tr><tr><td>加权轮询</td><td>按权重分配</td><td>新旧机器混用</td><td>权重凭经验，靠监控校准</td></tr><tr><td>最少连接 Least Connections</td><td>分给连接数最少者</td><td>长连接/请求耗时差异大</td><td>连接数 ≠ 负载（计算密集型请求）</td></tr><tr><td>IP Hash</td><td>同 IP 固定到同一后端</td><td>会话保持的简单方案</td><td>客户端 IP 变化（移动网络）失效</td></tr><tr><td>一致性哈希</td><td>按哈希环映射</td><td>缓存集群、需要稳定映射</td><td>节点变化只影响部分 key</td></tr></tbody></table><p>算法没有「最好」，只有「匹配场景」。无状态服务轮询 + 健康检查就够；<strong>任何「带状态」的需求（会话、缓存亲和）都要先问：能不能把状态拿出来（Redis 存 session），而不是绑定后端</strong>。</p><h4 id="_3-健康检查" tabindex="-1">3. 健康检查 <a class="header-anchor" href="#_3-健康检查" aria-label="Permalink to &quot;3. 健康检查&quot;">​</a></h4><p>LB 必须能感知后端故障，否则会把请求打到挂掉的机器上：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主动检查（LB 定期探测）：</span></span>
<span class="line"><span>  间隔 5s 发 GET /healthz，要求 200 且响应体 &quot;ok&quot;</span></span>
<span class="line"><span>  → 连续 2 次失败剔除（不再转发）</span></span>
<span class="line"><span>  → 连续 3 次成功恢复（重新加入）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>被动检查（根据真实请求结果）：</span></span>
<span class="line"><span>  后端连续返回 5xx → 熔断剔除</span></span>
<span class="line"><span>  连接超时次数超阈值 → 剔除</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/healthz 接口的设计要点：</span></span>
<span class="line"><span>  ✅ 只检查自身存活（进程 + 依赖的关键资源轻量探测）</span></span>
<span class="line"><span>  ❌ 不要在 /healthz 里检查数据库连通性——</span></span>
<span class="line"><span>     数据库抖动会让整台机器被摘掉，引发雪崩式重启</span></span></code></pre></div><h4 id="_4-会话保持-从-sticky-到无状态" tabindex="-1">4. 会话保持：从 sticky 到无状态 <a class="header-anchor" href="#_4-会话保持-从-sticky-到无状态" aria-label="Permalink to &quot;4. 会话保持：从 sticky 到无状态&quot;">​</a></h4><p>有状态需求（用户 session 在后端内存）需要保证同一用户始终打到同一台后端：</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>评价</th></tr></thead><tbody><tr><td>Sticky Session</td><td>LB 记住「用户 → 后端」映射</td><td>简单但后端重启/扩容即失效，且分布不均</td></tr><tr><td>IP Hash</td><td>同 IP 同后端</td><td>同上，且 NAT 环境失效</td></tr><tr><td><strong>无状态化</strong></td><td>session 存 Redis/Token 带签名</td><td>推荐：后端可以任意横向扩缩容</td></tr></tbody></table><p>权衡结论：<strong>会话保持是「补丁」，无状态化才是「根治」</strong>。设计时优先把状态外置（Redis 存 session、JWT 存身份），让任何请求可以打到任何后端——LB 算法退化为最简单的轮询，集群扩容缩容再无约束。</p><h4 id="_5-负载均衡自身的高可用-vip" tabindex="-1">5. 负载均衡自身的高可用（VIP） <a class="header-anchor" href="#_5-负载均衡自身的高可用-vip" aria-label="Permalink to &quot;5. 负载均衡自身的高可用（VIP）&quot;">​</a></h4><p>LB 是流量必经之路，<strong>LB 挂了整个系统就挂了</strong>——所以 LB 本身必须冗余。业界标准做法是「主备 + VIP 漂移」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                虚拟 IP（VIP：对外只暴露这一个 IP）</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>        ┌───────────────┴───────────────┐</span></span>
<span class="line"><span>        ▼                               ▼</span></span>
<span class="line"><span>    LB 主（keepalived 节点1）        LB 备（keepalived 节点2）</span></span>
<span class="line"><span>        │         心跳（VRRP 组播）       │</span></span>
<span class="line"><span>        └───────────────┬───────────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>                    后端集群</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主 LB 故障 → 心跳中断 → 备节点接管 VIP（约 1s）</span></span>
<span class="line"><span>→ 客户端无感知，连接打到备节点继续服务</span></span></code></pre></div><p>两个细节：一是<strong>主备是「双活」还是「主备」</strong>——双活需要会话同步，复杂度高；一般读多场景主备足够。二是 LB 自身的容量：它转发所有流量，CPU/网卡量级要按「峰值 QPS + 余量」配置，常见事故就是「LB 成为唯一瓶颈」。</p><h4 id="_6-nginx-最小配置实战" tabindex="-1">6. Nginx 最小配置实战 <a class="header-anchor" href="#_6-nginx-最小配置实战" aria-label="Permalink to &quot;6. Nginx 最小配置实战&quot;">​</a></h4><p>把上面的概念落到一份可运行的 Nginx 配置（L7 + 健康检查 + 加权轮询）：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nginx.conf —— 负载均衡最小配置</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">upstream</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> backend_api </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 加权轮询：新机器 weight 低，性能好的机器 weight 高</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 10.0.0.11:8080 </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">weight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    server 10.0.0.12:8080 </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">weight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    server 10.0.0.13:8080 </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">weight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 新扩容机器，先少分流量</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 主动健康检查：每 5s 探一次 /healthz，失败 2 次剔除，恢复 3 次回池</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    check interval=5000 rise=3 fall=2 timeout=2000;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 按请求头做会话保持（无状态化后的可选增强）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        hash </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$remote_addr consistent;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 一致性哈希：节点变化影响最小</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://backend_api;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 后端拿真实客户端 IP</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>对照第 2 节算法表看这份配置：生产环境几乎不会用纯轮询，而是<strong>加权轮询 + 一致性哈希 + 健康检查</strong>的组合——每行配置背后都是一个权衡决策。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>有状态服务直接轮询</strong>：session 存内存却开轮询，用户一会登录一会掉线；状态外置或加 sticky，二选一。</li><li><strong>健康检查接口查数据库</strong>：数据库抖动导致整批后端被摘掉，故障被放大成雪崩；/healthz 只查自身。</li><li><strong>跳过 LB 直连后端</strong>：扩容时后端 IP 变了，客户端配置跟着改——一切出入口必须过 LB，后端 IP 对业务透明。</li><li><strong>只做一层 LB</strong>：DDoS 到 L4 LB 之前没有清洗层，LB 直接被打瘫；要考虑入口分层（云 WAF/清洗 → LB → 后端）。</li><li><strong>忽略 LB 自身容量</strong>：LB 只占 1 台 2 核机器，流量涨了先崩的是 LB 而不是后端。</li><li><strong>L7 当 L4 用（或反之）</strong>：数据库入口用 Nginx 做 L7 转发，徒增开销还引入解析风险；内部组件用 L4 即可。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用 Nginx 在你本地搭建 L7 负载均衡：两个后端（如 8001/8002 端口的简单服务）+ 轮询 + <code>/healthz</code> 健康检查，验证摘除一台后端后流量自动转移。</li><li><strong>进阶</strong>：给上面的集群加上「IP Hash 会话保持」和「主备 VIP 方案」：画出 VIP 漂移时序，说明 keepalived 心跳中断后客户端请求如何恢复。</li><li><strong>综合</strong>：设计一个电商系统的流量入口：客户端 → CDN → WAF/清洗 → L4 → Nginx(L7) → 应用集群，标注每一层解决什么问题、哪层挂了如何处理（降级策略）。</li></ol><blockquote><p>用 <code>/practice system-design 负载均衡</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>Webpack DevServer proxy（按路径转发）</td><td>L7 负载均衡（按 URL 路由）</td></tr><tr><td>CDN 按地理位置调度</td><td>全局负载均衡（GSLB）</td></tr><tr><td>React Query 缓存无状态化（服务端状态外置）</td><td>无状态化：session 外置到 Redis</td></tr><tr><td>组件懒加载（按需加载 chunk）</td><td>按路径分流（/static 与 /api 分集群）</td></tr><tr><td>浏览器缓存刷新策略</td><td>健康检查与故障剔除（去掉坏资源）</td></tr><tr><td>微前端入口路由（基座分发）</td><td>网关层按域名的 L7 分发</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://nginx.org/en/docs/http/load_balancing.html" target="_blank" rel="noreferrer">Nginx 负载均衡官方文档</a></li><li><a href="https://www.haproxy.org/doc/1.8/intro/architecture.html" target="_blank" rel="noreferrer">HAProxy 架构文档</a></li><li><a href="http://www.linuxvirtualserver.org/" target="_blank" rel="noreferrer">LVS（Linux Virtual Server）项目</a></li></ul>`,38)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
